import adsk.core, adsk.fusion, json, math
PATH='/Users/daiki/Projects/sage60/mechanical/gasket_v1/source_geometry.json'
def pt(x,y): return adsk.core.Point3D.create(x/10.0,-y/10.0,0)
def build_chain(edges):
    pending=[dict(e) for e in edges]
    first=pending.pop(0)
    chain=[first]; cur=list(first['end'])
    while pending:
        best=None
        for i,e in enumerate(pending):
            d=((cur[0]-e['start'][0])**2+(cur[1]-e['start'][1])**2)**0.5
            dr=((cur[0]-e['end'][0])**2+(cur[1]-e['end'][1])**2)**0.5
            if best is None or min(d,dr)<best[0]: best=(min(d,dr),i,dr<d)
        dist,i,rev=best; e=pending.pop(i)
        if dist>0.02: raise RuntimeError('edge gap '+str(dist))
        if rev:
            e={'type':e['type'],'start':e['end'],'end':e['start'],'mid':e.get('mid')}
        join=[(cur[0]+e['start'][0])/2,(cur[1]+e['start'][1])/2]
        chain[-1]['end']=join; e['start']=join; chain.append(e); cur=list(e['end'])
    dist=((cur[0]-chain[0]['start'][0])**2+(cur[1]-chain[0]['start'][1])**2)**0.5
    if dist>0.02: raise RuntimeError('closing gap '+str(dist))
    join=[(cur[0]+chain[0]['start'][0])/2,(cur[1]+chain[0]['start'][1])/2]
    chain[-1]['end']=join; chain[0]['start']=join
    return chain
def make_sk(root,name,chain):
    sk=root.sketches.add(root.xYConstructionPlane); sk.name=name
    for e in chain:
        if e['type']=='Line':
            sk.sketchCurves.sketchLines.addByTwoPoints(pt(*e['start']),pt(*e['end']))
        else:
            sk.sketchCurves.sketchArcs.addByThreePoints(pt(*e['start']),pt(*e['mid']),pt(*e['end']))
    return sk
def inspect(sk):
    arr=[]
    for j in range(sk.profiles.count):
        p=sk.profiles.item(j); bb=p.boundingBox
        arr.append({'j':j,'area':p.areaProperties().area,'bb':[[bb.minPoint.x,bb.minPoint.y],[bb.maxPoint.x,bb.maxPoint.y]],'loops':p.profileLoops.count})
    return arr
def run(_context):
    app=adsk.core.Application.get(); doc=app.documents.add(adsk.core.DocumentTypes.FusionDesignDocumentType)
    des=adsk.fusion.Design.cast(doc.products.itemByProductType('DesignProductType')); root=des.rootComponent
    data=json.load(open(PATH)); out={}
    for side in ('left','right'):
        chain=build_chain(data[side]['edges']); sk=make_sk(root,side+'_raw',chain)
        bb=sk.profiles.item(0).boundingBox
        oc=adsk.core.ObjectCollection.create()
        loop=sk.profiles.item(0).profileLoops.item(0)
        for j in range(loop.profileCurves.count): oc.add(loop.profileCurves.item(j).sketchEntity)
        dcen=adsk.core.Point3D.create((bb.minPoint.x+bb.maxPoint.x)/2,(bb.minPoint.y+bb.maxPoint.y)/2,0)
        douter=adsk.core.Point3D.create(bb.minPoint.x-1,bb.minPoint.y-1,0)
        sk_inside=make_sk(root,side+'_inside',chain)
        oc2=adsk.core.ObjectCollection.create(); loop2=sk_inside.profiles.item(0).profileLoops.item(0)
        for j in range(loop2.profileCurves.count): oc2.add(loop2.profileCurves.item(j).sketchEntity)
        r1=sk_inside.offset(oc2,dcen,0.15)
        sk_out=make_sk(root,side+'_outside',chain)
        oc3=adsk.core.ObjectCollection.create(); loop3=sk_out.profiles.item(0).profileLoops.item(0)
        for j in range(loop3.profileCurves.count): oc3.add(loop3.profileCurves.item(j).sketchEntity)
        r2=sk_out.offset(oc3,douter,0.15)
        out[side]={'raw':inspect(sk),'inside':inspect(sk_inside),'outside':inspect(sk_out),'new_inside':r1.count if r1 else None,'new_outside':r2.count if r2 else None}
    print(json.dumps(out))
    doc.close(False)
